#include "wdog_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

SInt16 wdog_init (const Wdog_Clk_Mode clk_mode , UInt32 timeout)
{
  CRITICAL ;

  SInt16 status ;

  C_ENTER ;
    {
      WDTC     = timeout < 0xFF ? 0xFF : timeout ; // User manual specifies minimum timeout value of 0xFF

      WDCLKSEL = clk_mode ;

      #define BIT(z) ((UInt32) 1 << z)

      if (WDMOD & BIT (2))
        {
          status = WDOG_RESET_CODE ;

          WDMOD &= ~ BIT(2) ;
        }
      else
        {
          status = WDOG_RESET_POWERUP ;
        }

      WDOG_RESET_CODE = WDOG_RESET_TIMEOUT ;

      #undef BIT
    }
  C_LEAVE ;

  return status ;
}

